// Resolve complete GSC schemas before filtering; never guess between aliases or dimensions.
function gscRows(text,sep,filter){
 const [header,...body]=parseCSV(text,sep),map=new Map();
 req(header?.length&&body.length<=50000,'CSV-Kopfzeile und höchstens 50.000 Datenzeilen erforderlich.');
 const columns=header.map(normalizeKeyword);
 req(columns.every(Boolean)&&new Set(columns).size===columns.length,'Eindeutige, nicht leere CSV-Spaltennamen erforderlich.');
 const aliases={query:['query','queries','suchanfrage','suchanfragen','top-suchanfragen','top suchanfragen','häufigste suchanfragen','top queries'],page:['url','page','pages','seite','seiten','top-seiten','top seiten','top pages'],clicks:['clicks','klicks'],impressions:['impressions','impressionen']};
 const matches=name=>columns.flatMap((column,index)=>aliases[name].includes(column)?[index]:[]);
 const queries=matches('query'),pages=matches('page'),clicks=matches('clicks'),impressions=matches('impressions');
 req(queries.length+pages.length===1,'Genau eine Dimension erforderlich: query/Suchanfragen/Top queries oder url/Seiten/Top pages. Mehrere Dimensionsspalten vorher getrennt exportieren.');
 req(clicks.length===1&&impressions.length===1,'Genau eine Klicks- und eine Impressionsspalte erforderlich; doppelte Alias-Spalten wie clicks/Klicks sind mehrdeutig.');
 const dimension=queries.length?'query':'page',key=(queries.length?queries:pages)[0],needle=String(filter).toLocaleLowerCase('de');
 for(const [rowIndex,row] of body.entries()){
  req(row.length===header.length,`Zeile ${rowIndex+2}: falsche Spaltenzahl.`);
  const label=row[key];req(label.trim(),`Zeile ${rowIndex+2}: leere Suchanfrage oder Seite.`);
  let c,i;try{c=count(row[clicks[0]]);i=count(row[impressions[0]]);req(c<=i,'Klicks dürfen Impressionen nicht überschreiten.');}catch(error){throw Error(`Zeile ${rowIndex+2}: ${error.message}`);}
  // Validate all rows even when the chosen display filter would hide them.
  if(!label.toLocaleLowerCase('de').includes(needle))continue;
  const current=map.get(label)||{clicks:0,impressions:0};current.clicks+=c;current.impressions+=i;
  req(Number.isSafeInteger(current.clicks)&&Number.isSafeInteger(current.impressions),'Aggregat zu groß.');map.set(label,current);
 }
 return {map,dimension};
}
add('T038',{data:t('Aktueller CSV-Export: query,clicks,impressions','query,clicks,impressions\nseo,25,1000\nseo,15,500\ngeo,5,800'),baseline:t('Vergleichszeitraum (optional, gleiche Dimension und Filter)',''),sep:sel('Trennzeichen',[',',';','\t']),filter:t('Suchfilter (enthält)','','text'),order:sel('Sortierung',['Impressionen','Klicks','Klickverlust','Klickgewinn'])},v=>{
 const current=gscRows(v.data,v.sep,v.filter),baseline=v.baseline.trim()?gscRows(v.baseline,v.sep,v.filter):null;
 req(!baseline||current.dimension===baseline.dimension,'Vergleich benötigt dieselbe Dimension: Suchanfragen und Seiten dürfen nicht miteinander verglichen werden.');
 req(baseline||!['Klickverlust','Klickgewinn'].includes(v.order),'Für Klickverlust oder Klickgewinn einen Vergleichsexport angeben.');
 const now=current.map,previous=baseline?.map,keys=new Set([...now.keys(),...(previous?.keys()||[])]);
 const rows=[...keys].map(query=>{
  const cur=now.get(query)||{clicks:0,impressions:0},row={query,dimension:current.dimension,...cur,ctr:pct(cur.clicks,cur.impressions)};
  if(!previous)return row;
  const prev=previous.get(query)||{clicks:0,impressions:0};
  return {...row,previousClicks:prev.clicks,previousImpressions:prev.impressions,previousCtr:pct(prev.clicks,prev.impressions),clickDelta:cur.clicks-prev.clicks,impressionDelta:cur.impressions-prev.impressions,ctrDeltaPP:cur.impressions&&prev.impressions?rnd((cur.clicks/cur.impressions-prev.clicks/prev.impressions)*100):null,presence:now.has(query)&&previous.has(query)?'beide Exporte':now.has(query)?'nur aktueller Export':'nur Vergleichsexport'};
 });
 const field=v.order==='Klicks'?'clicks':v.order.startsWith('Klick')?'clickDelta':'impressions',dir=v.order==='Klickverlust'?1:-1;
 rows.sort((a,b)=>dir*(a[field]-b[field])||a.query.localeCompare(b.query,'de'));
 return output(j(rows),{type:'bars',data:Object.fromEntries(rows.slice(0,12).map(x=>[x.query,x.impressions]))});
},'Aggregiert Search-Performance-Exporte mit Klicks und Impressionen und gewichtet CTR. Erkennt deutsche/englische Query- oder Seitenspalten, prüft alle Zeilen vor dem Filtern und vergleicht nur dieselbe Dimension. Klick-/Impressionsdifferenzen und CTR-Änderungen in Prozentpunkten bleiben getrennt.','Nur Query- oder Seitenexporte mit Klicks und Impressionen; reine Impressionsdateien aus dem separaten Bericht zur generativen KI werden nicht unterstützt. Maximal 50.000 Zeilen pro Export; exakte ganze Zählwerte ohne Tausendertrennzeichen. Vergleich nur bei gleich langen Zeiträumen und identischen Filtern; diese Metadaten stehen nicht im CSV und werden nicht automatisch verifiziert. Fehlende Zeilen sind keine belegten Verluste. Google exportiert nicht verfügbare UI-Werte (~ oder -) als 0; diese frühere Unterscheidung lässt sich aus dem CSV nicht wiederherstellen. Keine Kausalitätsanalyse; anonymisierte oder begrenzte GSC-Daten können fehlen.','json');
add('T039',{data:t('Begriffe, je Zeile','seo tools\ngeo+ki\nrobots.txt'),mode:sel('Modus',['enthält','exakt']),sample:t('Testzeilen','seo tools kostenlos\nrobots.txt\nrobotsXtxt')},v=>{let a=lines(v.data);req(a.length,'Mindestens ein Begriff erforderlich.');let re='(?:'+a.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')';if(v.mode==='exakt')re='^'+re+'$';let r=new RegExp(re,'i');return re+'\n\n'+lines(v.sample).map(s=>(r.test(s)?'✓ ':'– ')+s).join('\n');},'Maskiert Regex-Metazeichen und kombiniert Begriffe per Alternation.','Test nutzt JavaScript mit i-Flag. Search Console verwendet RE2 und prüft standardmäßig ohne Beachtung der Groß-/Kleinschreibung; (?-i) erzwingt dort Beachtung. RE2 unterstützt nicht alle JS-Features.');
add('T040',{impressions:num('Impressionen / Monat',10000),old:num('Bisherige CTR (%)',2,0,100),low:num('Ziel-CTR niedrig (%)',3,0,100),high:num('Ziel-CTR hoch (%)',5,0,100),cvr:num('Conversion Rate (%)',2,0,100)},v=>{req(n(v.high)>=n(v.low),'Zielspanne muss aufsteigend sein.');let base=n(v.impressions)*n(v.old)/100;return j({Bisher:base,Szenarien:[v.low,v.high].map(x=>({CTR:n(x),Klicks:rnd(n(v.impressions)*n(x)/100),Zusatzklicks:rnd(n(v.impressions)*n(x)/100-base),Conversions:rnd(n(v.impressions)*n(x)/100*n(v.cvr)/100)}))});},'Klicks = Impressionen × CTR; Conversions = Klicks × Conversion Rate.','Reine Szenarien bei konstanten Impressionen, keine Ranking- oder Umsatzprognose.');
add('T041',{traffic:num('Zusätzliche Besuche / Monat',2000),cvr:num('Conversion Rate (%)',2,0,100),value:num('Deckungsbeitrag je Conversion (€)',60),cost:num('Gesamtkosten (€)',5000),months:num('Zeitraum (Monate)',6,1,120,1)},v=>{let b=n(v.traffic)*n(v.cvr)/100*n(v.value)*n(v.months);return j({Deckungsbeitrag:rnd(b),Nettoeffekt:rnd(b-n(v.cost)),ROI:pct(b-n(v.cost),n(v.cost))});},'Setzt zusätzlichen Deckungsbeitrag nach Kosten ins Verhältnis zu den Kosten.','Konstante Monatsannahmen; keine Abzinsung, Steuern oder Kausalitätsmessung.');
add('T042',{data:t('CSV: position,clicks,impressions','position,clicks,impressions\n1,200,1000\n2,120,1000\n3,70,1000')},v=>{let m={};for(let a of records(v.data)){let p=Math.floor(n(a.position)),c=count(a.clicks),i=count(a.impressions);req(Number.isSafeInteger(p)&&p>=1&&Number.isSafeInteger(c)&&Number.isSafeInteger(i)&&c>=0&&i>=c,'Position ≥ 1 und nichtnegative sichere Ganzzahlen für Klicks/Impressionen erforderlich; Klicks dürfen Impressionen nicht überschreiten.');let z=m[p]??=[0,0];z[0]+=c;z[1]+=i;req(z.every(Number.isSafeInteger),'Aggregierte Zählwerte außerhalb des sicheren Ganzzahlbereichs.');}let data=Object.fromEntries(Object.entries(m).map(([p,[c,i]])=>[p,i?rnd(c/i*100):0]));return output(j(data),{type:'bars',data});},'Gruppiert Positionen nach ganzzahligem Intervall und berechnet CTR aus Summen.','Positionsmittelwerte sind keine tatsächlichen Einzelrankings; 0 bei fehlenden Impressionen ist nur Diagrammkonvention.');
add('T043',{impr:num('Impressionen',100000),click:num('Klicks',1500),conv:num('Conversions',40),cost:num('Kosten (€)',900),revenue:num('Umsatz (€)',4000)},v=>{let [i,c,k,s,r]=['impr','click','conv','cost','revenue'].map(x=>n(v[x]));req(c<=i,'Klicks dürfen für dieses einfache Modell Impressionen nicht überschreiten.');return j({CTR:pct(c,i),CPC:div(s,c),CPM:div(s*1000,i),CPA:div(s,k),CVR:pct(k,c),ROAS:div(r,s)});},'Berechnet gebräuchliche Marketing-KPIs und behandelt Nenner null explizit.','Einheitliche Zeiträume, Attribution und Kostenbasis vorausgesetzt.');
add('T044',{na:num('Gruppe A: Nutzer',1000,1,1e9,1),ca:num('A: Conversions',50,0,1e9,1),nb:num('Gruppe B: Nutzer',1000,1,1e9,1),cb:num('B: Conversions',70,0,1e9,1)},v=>{let [a,x,b,y]=['na','ca','nb','cb'].map(k=>n(v[k]));req([a,x,b,y].every(Number.isInteger)&&x<=a&&y<=b,'Ganzzahlige Conversions ≤ Nutzer erforderlich.');req(Math.min(x,a-x,y,b-y)>=10,'Normalapproximation unzuverlässig: mindestens 10 Erfolge und Misserfolge pro Gruppe erforderlich.');let pa=x/a,pb=y/b,d=pb-pa,se=Math.sqrt(pa*(1-pa)/a+pb*(1-pb)/b);return j({A:pct(x,a),B:pct(y,b),'Differenz Prozentpunkte':rnd(d*100),'95%-KI Prozentpunkte (Wald)':[(d-1.96*se)*100,(d+1.96*se)*100].map(x=>rnd(x))});},'Berechnet ein approximatives zweiseitiges 95%-Wald-Intervall für die Differenz zweier unabhängiger Anteile.','Nur bei ausreichend Erfolgen/Misserfolgen; keine fortlaufenden Zwischenstopps, keine Mehrfachtestkorrektur oder kausale Garantie.');
add('T045',{data:t('Referrer | Sitzungen','https://chatgpt.com/ | 42\nhttps://example.org/ | 15\nhttps://www.perplexity.ai/ | 8'),domains:t('Bekannte KI-Domains','chatgpt.com\nperplexity.ai\nclaude.ai\ngemini.google.com')},v=>{let d=lines(v.domains).map(x=>x.toLowerCase()),m=Object.create(null);for(let [u,c] of pairs(v.data)){let h=url(u).hostname,k=d.find(x=>h===x||h.endsWith('.'+x))||'Unbekannt / sonstige';const sessions=count(c),total=(m[k]||0)+sessions;req(Number.isSafeInteger(total),'Aggregierte Sitzungen außerhalb des sicheren Ganzzahlbereichs.');m[k]=total;}return output(j(m),{type:'bars',data:m});},'Ordnet Referrer über explizite Domainregeln zu.','KI-Zugriffe ohne Referrer oder über andere Kanäle bleiben unbekannt; kein Zugriff auf GA4.');
