add('T088',{speed:num('Horizontale Geschwindigkeit (px/s)',220,0,2000),jump:num('Absprunggeschwindigkeit (px/s)',500,1,2000),gravity:num('Schwerkraft (px/s²)',980,1,5000)},v=>{let x=n(v.speed),u=n(v.jump),g=n(v.gravity),time=2*u/g;return output(j({Flugzeit:rnd(time,3),Höhe:rnd(u*u/(2*g)),Reichweite:rnd(x*time)}),{type:'parabola',points:Array.from({length:51},(_,i)=>{let t=time*i/50;return [x*t,u*t-g*t*t/2];})});},'Verwendet konstante Schwerkraft und horizontale Geschwindigkeit: h=v²/(2g), T=2v/g.','Idealisierter Sprung auf gleicher Höhe, ohne Luftsteuerung, Kollisionen oder variable Sprunghöhe.');
