add('T090',{data:t('Item | Gewicht','Gewöhnlich | 80\nSelten | 18\nEpisch | 2'),draws:num('Ziehungen',10000,1,100000,1),seed:t('Seed','loot-demo','text')},v=>{let a=pairs(v.data).map(([k,w])=>[k,n(w)]);req(new Set(a.map(x=>x[0])).size===a.length&&a.every(x=>x[1]>=0),'Eindeutige Namen und nichtnegative Gewichte erforderlich.');req(a.length<=200,'Maximal 200 Einträge.');let shares=normalizedWeights(a.map(x=>x[1])),r=seedRand(v.seed),counts=a.map(()=>0);for(let k=0;k<n(v.draws);k++){let q=r(),i=0;while(i<a.length-1&&q>=shares[i])q-=shares[i++];counts[i]++;}let rows=a.map(([k,w],i)=>({Item:k,Theorie:pct(shares[i],1),Simulation:counts[i]}));return output(j(rows),{type:'bars',data:Object.fromEntries(a.map(([k],i)=>[k,counts[i]]))});},'Simuliert gewichtete unabhängige Ziehungen mit deterministischem Seed.','Kein kryptografischer Zufall, kein Echtgeld- oder Glücksspielsystem; Stichprobenschwankungen sind normal.');
export function astar(grid,start,end){const H=grid.length,W=grid[0].length,key=(x,y)=>y*W+x,dist=(x,y)=>Math.abs(x-end[0])+Math.abs(y-end[1]);let open=[{x:start[0],y:start[1],g:0,f:dist(...start)}],best=new Map([[key(...start),0]]),prev=new Map(),visited=[];while(open.length){open.sort((a,b)=>a.f-b.f||a.g-b.g);let c=open.shift(),k=key(c.x,c.y);if(c.g!==best.get(k))continue;visited.push([c.x,c.y]);if(c.x===end[0]&&c.y===end[1]){let p=[],i=k;while(i!==undefined){p.push([i%W,Math.floor(i/W)]);i=prev.get(i);}return {path:p.reverse(),visited};}for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let x=c.x+dx,y=c.y+dy;if(x<0||x>=W||y<0||y>=H||grid[y][x])continue;let nk=key(x,y),g=c.g+1;if(g<(best.get(nk)??Infinity)){best.set(nk,g);prev.set(nk,k);open.push({x,y,g,f:g+dist(x,y)});}}}return {path:[],visited};}
